output_text:
[
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "Shoppers must not take a shopping cart into a single-file aisle bounded by shelves.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    },
    "justification": "The rule is defined by aisle width and neighbouring shelves rather than by particular cells, so it applies to any store with narrow shelf aisles."
  },
  {
    "id": "park_before_entering_single_file_aisle",
    "text": "A shopper carrying a cart must park it before moving into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileShelfAisle": {
          "pre": {
            "or": [
              "N",
              "S",
              "E",
              "W"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "enterSingleFileShelfAisle"
        ]
      }
    },
    "justification": "It refers to entering a physically constrained aisle type, not to a named aisle or coordinate in this layout."
  },
  {
    "id": "no_cart_while_selecting_in_single_file_aisle",
    "text": "Shelf interactions inside a single-file shelf aisle should be performed without holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    },
    "justification": "The constraint is about how to behave when selecting goods in cramped shelf aisles, a relation that can be detected in any store geometry."
  },
  {
    "id": "park_cart_only_in_wide_staging_area",
    "text": "If a shopper sets down a cart, it should be parked only in a wide unobstructed staging area away from shelf edges.",
    "abstraction": {
      "state_properties": {
        "wideUnobstructedStagingArea": {
          "and": [
            {
              "not": "adjShelf"
            },
            {
              "ge": [
                "freeWidthH",
                3
              ]
            },
            {
              "ge": [
                "freeWidthV",
                3
              ]
            }
          ]
        }
      },
      "events": {
        "setDownCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "setDownCart",
          {
            "not": "wideUnobstructedStagingArea"
          }
        ]
      }
    },
    "justification": "The rule uses generic clearance and shelf-adjacency properties to identify safe parking places rather than memorising where carts were parked."
  },
  {
    "id": "retrieve_parked_cart",
    "text": "A shopper who parks a cart is obliged to retrieve it before leaving the store.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "setDownCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "pickUpCart": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "setDownCart",
      "discharge": "pickUpCart"
    },
    "justification": "Retrieving a cart after parking it is a general shopping practice independent of where the cart was parked in the particular floor plan."
  },
  {
    "id": "no_exit_without_cart",
    "text": "A shopper should not exit the supermarket without the cart they obtained.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    },
    "justification": "The exit-with-cart requirement depends only on the shopper's possession of a cart at checkout or exit, not on the store's layout."
  },
  {
    "id": "must_obtain_cart_at_start",
    "text": "At the start of a shopping trip, the shopper is obliged to obtain a cart.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "acquireCart": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    },
    "justification": "The norm concerns the general shopping role of using a cart and does not depend on the cart station's coordinates."
  },
  {
    "id": "keep_cart_at_accessible_shelf_front",
    "text": "When interacting with a shelf from a cart-accessible aisle, the shopper should keep the cart rather than leaving it behind.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "cartAccessibleShelfFront": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            },
            {
              "ge": [
                "freeWidthH",
                3
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "cartAccessibleShelfFront",
          {
            "not": "hasCart"
          }
        ]
      }
    },
    "justification": "The distinction between accessible shelf fronts and single-file shelf aisles is based on local clearance, so the rule transfers to different store layouts."
  }
]
